WITH x AS (SELECT st.slug, c.key AS camp, s.key AS strat, coalesce(s.value->>'date_start', e.period_start::date::string) AS d, max((s.value->>'spend')::float8) AS spend, max((s.value->>'impressions')::float8) AS imp, max((s.value->>'unique_clicks')::float8) AS clicks FROM recruitment_data_events e JOIN studies st ON st.id=e.study_id, jsonb_each(e.data) AS c, jsonb_each(c.value) AS s WHERE jsonb_typeof(c.value)='object' AND jsonb_typeof(s.value)='object' AND s.value->>'spend' IS NOT NULL AND st.slug IN ('embed-iraq','embed-egypt','embed-ksa','embed-morocco','embed-jordan') GROUP BY 1,2,3,4)
SELECT slug, strat, d, spend, imp, clicks FROM x ORDER BY 1,2,3;
